import 'package:flutter_bloc/flutter_bloc.dart'; import '../../../products/domain/failures/product_failure.dart'; import '../../domain/repositories/product_detail_repository.dart'; import '../../domain/usecases/get_product_detail_use_case.dart'; import 'product_detail_state.dart';
class ProductDetailCubit extends Cubit<ProductDetailState> { ProductDetailCubit({required GetProductDetailUseCase getDetail, required ProductDetailRepository repository}) : _getDetail = getDetail, _repository = repository, super(const ProductDetailInitial()); final GetProductDetailUseCase _getDetail; final ProductDetailRepository _repository; int? _id;
  Future<void> load(int id) async { _id = id; emit(const ProductDetailLoading()); try { emit(ProductDetailLoaded(await _getDetail(id))); } on ProductFailure catch (failure) { final cached = await _repository.readCached(id); if (cached != null) { emit(ProductDetailLoaded(cached, isOffline: failure.isOffline)); } else if (failure.isOffline) { emit(const ProductDetailOffline()); } else { emit(ProductDetailFailure(failure, canRetry: !failure.requiresReauthentication)); } } catch (_) { emit(const ProductDetailFailure(ProductUnexpectedFailure(), canRetry: true)); } }
  Future<void> retry() => _id == null ? Future.value() : load(_id!);
}
